def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    count = 3
    value = (v1 + v2 + v3) / count
    return {
        "value": value,
        "trace": {
            "values": [v1, v2, v3],
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
